import { supabase } from "./supabase.js";

const $ = (id) => document.getElementById(id);

async function loadProfile(user) {
  const { data } = await supabase.from("profiles").select("id, display_name, role").eq("user_id", user.id).maybeSingle();
  if (!data) await supabase.from("profiles").insert({ user_id: user.id, display_name: user.email });
  $("who").textContent = data?.display_name ?? user.email;
}

async function loadTodos(user) {
  const { data } = await supabase.from("todos").select("id, title, done, created_at").eq("user_id", user.id).order("created_at");
  $("todos").innerHTML = (data ?? []).map((t) => `<li>${t.done ? "✓" : "○"} ${t.title}</li>`).join("");
  const { data: count } = await supabase.rpc("get_my_todo_count");
  $("count").textContent = String(count ?? 0);
}

async function addTodo(user, title) {
  await supabase.from("todos").insert({ user_id: user.id, title, done: false });
}

async function loadNotes(user) {
  const { data } = await supabase.from("notes").select("id, body").eq("owner_id", user.id);
  $("notes").innerHTML = (data ?? []).map((n) => `<li>${n.body}</li>`).join("");
}

async function loadAnnouncements() {
  const { data } = await supabase.from("announcements").select("id, title, body, published_at").order("published_at", { ascending: false });
  $("news").innerHTML = (data ?? []).map((a) => `<li><b>${a.title}</b> ${a.body ?? ""}</li>`).join("");
}

async function uploadAvatar(user, file) {
  await supabase.storage.from("avatars").upload(`${user.id}/avatar.png`, file, { upsert: true });
}

$("login").addEventListener("submit", async (e) => {
  e.preventDefault();
  const { data, error } = await supabase.auth.signInWithPassword({ email: $("email").value, password: $("password").value });
  if (error) return alert(error.message);
  start(data.user);
});

async function start(user) {
  $("app").hidden = false;
  await Promise.all([loadProfile(user), loadTodos(user), loadNotes(user)]);
  $("add").onclick = async () => { await addTodo(user, $("title").value); loadTodos(user); };
  $("avatar").onchange = (e) => uploadAvatar(user, e.target.files[0]);
  $("billing").onclick = async () => { const m = await import("./billing.js"); m.showBilling(user); };
  $("inbox").onclick = async () => { const m = await import("./inbox.js"); m.showInbox(user); };
}

loadAnnouncements();
supabase.auth.getUser().then(({ data }) => data.user && start(data.user));
